const cfg=window.EASY_CONFIG||{};
const login=document.querySelector('#login-panel'),dash=document.querySelector('#dashboard');
const loginMessage=document.querySelector('#login-message'),dashMessage=document.querySelector('#dashboard-message');
const day=document.querySelector('#day'),list=document.querySelector('#orders'),detail=document.querySelector('#detail');
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ulaanbaatar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
day.value=today();let db,orders=[],filter='active',seen=new Set(),firstLoad=true;
const statusText={new:'Шинэ',confirmed:'Баталгаажсан',on_way:'Замд гарсан',done:'Хийгдсэн',cancelled:'Цуцлагдсан'};
const serviceText={exterior:'Гадна угаалга',interior:'Дотор цэвэрлэгээ',full:'Бүтэн угаалга'};
const el=(tag,cls,text)=>{const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node};
const money=n=>Number(n||0).toLocaleString('en-US')+'₮';
function showLogin(message=''){dash.hidden=true;login.hidden=false;document.querySelector('#logout').hidden=true;document.querySelector('#notify').hidden=true;loginMessage.textContent=message}
async function load(){if(!db||dash.hidden)return;const {data,error}=await db.from('bookings').select('*').eq('booking_date',day.value).order('booking_hour');if(error){dashMessage.textContent='Захиалгуудыг ачаалж чадсангүй.';return}dashMessage.textContent='';orders=data||[];if(!firstLoad&&'Notification' in window){for(const o of orders){if(!seen.has(o.id)&&o.status==='new'&&Notification.permission==='granted')new Notification('Шинэ EASY CAR WASH захиалга',{body:`${o.name} · ${String(o.booking_hour).padStart(2,'0')}:00`,tag:o.id})}}seen=new Set(orders.map(o=>o.id));firstLoad=false;render()}
function render(){const active=orders.filter(o=>!['done','cancelled'].includes(o.status));const stats=[['Нийт',orders.length],['Идэвхтэй',active.length],['Шинэ',orders.filter(o=>o.status==='new').length],['Хийгдсэн',orders.filter(o=>o.status==='done').length]];document.querySelector('#stats').replaceChildren(...stats.map(([label,n])=>{const c=el('div','stat');c.append(el('span','',label),el('b','',String(n)));return c}));let shown=orders;if(filter==='active')shown=active;else if(filter!=='all')shown=orders.filter(o=>o.status===filter);list.replaceChildren();if(!shown.length){list.append(el('p','', 'Энэ өдөр энэ төлөвтэй захиалга алга.'));return}for(const o of shown){const card=el('button','order');card.type='button';card.append(el('span','time',`${String(o.booking_hour).padStart(2,'0')}:00`));const body=el('span');body.append(el('strong','',`${o.name} · ${o.vehicle_model}`),el('small','',`${serviceText[o.service]} · ${o.plate} · ${o.phone}`));card.append(body,el('span',`pill ${o.status}`,statusText[o.status]));card.onclick=()=>openOrder(o.id);list.append(card)}}
function section(title){const box=el('section','detail-section');box.append(el('h3','',title));return box}
function action(label,fn,primary=false){const b=el('button',primary?'primary':'',label);b.type='button';b.onclick=fn;return b}
async function patch(id,changes){const {error}=await db.from('bookings').update(changes).eq('id',id);if(error){alert('Өөрчлөлт хадгалагдсангүй.');return}await load();openOrder(id)}
async function openOrder(id){const o=orders.find(x=>x.id===id);if(!o)return;const root=document.querySelector('#detail-body');root.replaceChildren();const summary=section('Захиалга');for(const line of [`${String(o.booking_hour).padStart(2,'0')}:00 · ${o.booking_date}`,`${o.name} · ${o.phone}`,`${o.vehicle_model} · ${o.plate}`,serviceText[o.service],o.address])summary.append(el('p','',line));const links=el('div','inline');const phone=el('a','', 'Утасдах ↗');phone.href=`tel:${o.phone.replace(/[^+0-9]/g,'')}`;links.append(phone);if(o.latitude!=null&&o.longitude!=null){const map=el('a','', 'Google Maps ↗');map.href=`https://www.google.com/maps?q=${o.latitude},${o.longitude}`;map.target='_blank';map.rel='noopener';links.append(map)}summary.append(links);root.append(summary);
const workflow=section('Явц');const status=el('select');for(const [key,label] of Object.entries(statusText)){const option=el('option','',label);option.value=key;status.append(option)}status.value=o.status;status.onchange=()=>patch(id,{status:status.value});workflow.append(status);root.append(workflow);
const quote=section('Үнийн санал');quote.append(el('p','',o.quote_amount==null?'Үнэ хараахан илгээгээгүй':`${money(o.quote_amount)} · ${o.quote_status==='accepted'?'Зөвшөөрсөн':o.quote_status==='declined'?'Татгалзсан':'Хариу хүлээж байна'}`));const row=el('div','inline');const input=el('input');input.type='number';input.min='0';input.step='1000';input.placeholder='Үнэ ₮';input.value=o.quote_amount??'';row.append(input,action('Үнэ илгээх',()=>{const amount=Number(input.value);if(!Number.isInteger(amount)||amount<=0){alert('Үнийг зөв оруулна уу.');return}patch(id,{quote_amount:amount,quote_status:'offered'})},true));quote.append(row);root.append(quote);
const note=section('Дотоод тэмдэглэл');const textarea=el('textarea');textarea.value=o.admin_note||'';note.append(textarea,action('Тэмдэглэл хадгалах',()=>patch(id,{admin_note:textarea.value.slice(0,2000)})));root.append(note);
const messages=section('Хэрэглэгчтэй харилцах');const history=el('div','messages');messages.append(history);const compose=el('div','inline');const messageInput=el('input');messageInput.placeholder='Мессеж бичих';compose.append(messageInput,action('Илгээх',async()=>{const body=messageInput.value.trim();if(!body)return;const {error}=await db.from('booking_messages').insert({booking_id:id,sender:'admin',body});if(error){alert('Мессеж илгээгдсэнгүй.');return}messageInput.value='';loadMessages(id,history)},true));messages.append(compose);root.append(messages);loadMessages(id,history);if(!detail.open)detail.showModal()}
async function loadMessages(id,root){const {data}=await db.from('booking_messages').select('sender,body,created_at').eq('booking_id',id).order('created_at');root.replaceChildren();for(const m of data||[]){const bubble=el('div',`bubble ${m.sender}`);bubble.append(el('small','',`${m.sender==='admin'?'Админ':'Хэрэглэгч'} · ${new Date(m.created_at).toLocaleString('mn-MN')}`),el('span','',m.body));root.append(bubble)}if(!(data||[]).length)root.append(el('p','', 'Мессеж алга.'))}
async function verify(){const {data:{user}}=await db.auth.getUser();if(!user){showLogin();return}const {data,error}=await db.from('admin_users').select('user_id').eq('user_id',user.id).maybeSingle();if(error||!data){await db.auth.signOut();showLogin('Энэ бүртгэлд админ эрх олдоогүй.');return}login.hidden=true;dash.hidden=false;document.querySelector('#logout').hidden=false;document.querySelector('#notify').hidden=false;firstLoad=true;await load()}
document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();if(!db)return;loginMessage.textContent='Нэвтэрч байна…';const v=Object.fromEntries(new FormData(e.target));const {error}=await db.auth.signInWithPassword({email:v.email,password:v.password});if(error){loginMessage.textContent='Имэйл эсвэл нууц үг буруу байна.';return}verify()};
document.querySelector('#logout').onclick=async()=>{await db.auth.signOut();showLogin()};document.querySelector('#notify').onclick=async()=>{if('Notification'in window)await Notification.requestPermission()};document.querySelector('#refresh').onclick=load;day.onchange=()=>{firstLoad=true;load()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#close-detail').onclick=()=>detail.close();detail.onclick=e=>{if(e.target===detail)detail.close()};
if(cfg.supabaseUrl&&cfg.supabaseAnonKey){const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');db=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);verify();setInterval(load,15000)}else showLogin('Өгөгдлийн сан холбогдоогүй байна. config.js файлын public URL ба anon key-г тохируулна уу.');
